function validate([operations, args]) {
  if (operations[0] !== 'WordDistance' || args[0].length !== 1) return 'Start with WordDistance and its word list.';
  const wordsDict = args[0][0];
  if (wordsDict.length < 1 || wordsDict.length > 30000) return 'wordsDict needs 1 to 3 * 10^4 words.';
  if (wordsDict.some(w => !/^[a-z]{1,10}$/.test(w))) return 'Each word has 1 to 10 lowercase letters.';
  if (operations.length - 1 > 5000) return 'At most 5000 calls to shortest.';
  const known = new Set(wordsDict);
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'shortest') return 'Only shortest can follow the constructor.';
    const [word1, word2] = args[i];
    if (!known.has(word1) || !known.has(word2)) return 'Both query words must appear in wordsDict.';
    if (word1 === word2) return 'word1 and word2 must be different.';
  }
  return null;
}

