class WordDistance {
  constructor(wordsDict) {
    this.positions = new Map();
    for (let i = 0; i < wordsDict.length; i++) {
      const word = wordsDict[i];
      if (!this.positions.has(word)) {
        this.positions.set(word, []);
      }
      this.positions.get(word).push(i);
    }
  }

  shortest(word1, word2) {
    const first = this.positions.get(word1);
    const second = this.positions.get(word2);
    let i = 0;
    let j = 0;
    let best = Infinity;
    while (i < first.length && j < second.length) {
      best = Math.min(best, Math.abs(first[i] - second[j]));
      if (first[i] < second[j]) {
        i++;
      } else {
        j++;
      }
    }
    return best;
  }
}

