class WordDistance {
  constructor(wordsDict) {
    this.words = wordsDict.slice();
  }
  shortest(word1, word2) {
    // Scan the list remembering the latest place each word was seen.
    let last1 = -1, last2 = -1, best = Infinity;
    for (let k = 0; k < this.words.length; k++) {
      if (this.words[k] === word1) last1 = k;
      if (this.words[k] === word2) last2 = k;
      if (last1 >= 0 && last2 >= 0) best = Math.min(best, Math.abs(last1 - last2));
    }
    return best;
  }
}

