function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const makeWord = length => Array.from({ length }, () => letters[pick(26)]).join('');
  const vocabSize = size === 'large' ? 30 + pick(20) : 2 + pick(4);
  const vocab = [];
  while (vocab.length < vocabSize) {
    const word = size === 'large' ? makeWord(1 + pick(10)) : ['go', 'run', 'map', 'tree', 'a', 'b'][pick(6)];
    if (!vocab.includes(word)) vocab.push(word);
  }
  // Skew the choice so some words are common and others rare.
  const weight = vocab.map((_, i) => 1 / (i + 1));
  const total = weight.reduce((a, b) => a + b, 0);
  const choose = () => { let r = rand() * total; for (let i = 0; i < vocab.length; i++) { r -= weight[i]; if (r < 0) return vocab[i]; } return vocab[vocab.length - 1]; };
  const n = size === 'large' ? 2000 : 2 + pick(9);
  let wordsDict;
  for (;;) {
    wordsDict = Array.from({ length: n }, choose);
    if (new Set(wordsDict).size >= 2) break;
  }
  const present = [...new Set(wordsDict)];
  const operations = ['WordDistance'];
  const args = [[wordsDict]];
  const calls = size === 'large' ? 499 : 1 + pick(6);
  for (let c = 0; c < calls; c++) {
    const a = pick(present.length);
    let b = pick(present.length - 1);
    if (b >= a) b++;
    operations.push('shortest');
    args.push([present[a], present[b]]);
  }
  return [operations, args];
}
